00130 blink::pdb_reader::pdb_reader(const std::string &path) : msf_reader(path)
00131 {
00132     // PDB files should have 4 streams at the beginning that are always at the same index
00133     _is_valid &= stream_count() > 4;
00134 
00135     if (!is_valid())
00136         return;
00137 
00138     // Read PDB info stream
00139     stream_reader pdb_stream(msf_reader::stream(1));
00140     if (pdb_stream.size() == 0)
00141         return;
00142 
00143     const pdb_header &header = pdb_stream.read<pdb_header>();
00144     _version = header.version;
00145     _timestamp = header.time_date_stamp;
00146     _guid = header.guid;
00147 
00148     // Read stream names from string hash map
00149     pdb_stream.skip(header.names_map_offset);
00150 
00151     const auto count = pdb_stream.read<uint32_t>();
00152     const auto hash_table_size = pdb_stream.read<uint32_t>();
00153     _named_streams.reserve(count);
00154 
00155     const auto num_bitset_present = pdb_stream.read<uint32_t>();
00156     std::vector<uint32_t> bitset_present(num_bitset_present);
00157     pdb_stream.read(bitset_present.data(), num_bitset_present * sizeof(uint32_t));
00158 
00159     const auto num_bitset_deleted = pdb_stream.read<uint32_t>();
00160     pdb_stream.skip(num_bitset_deleted * sizeof(uint32_t));
00161 
00162     for (uint32_t i = 0; i < hash_table_size; i++)
00163     {
00164         if ((bitset_present[i / 32] & (1 << (i % 32))) == 0)
00165             continue;
00166 
00167         const auto name_offset = pdb_stream.read<uint32_t>();
00168         const auto stream_index = pdb_stream.read<uint32_t>();
00169 
00170         const auto pos = pdb_stream.tell();
00171         pdb_stream.seek(sizeof(header) + name_offset); // Seek into the string table that stores the name
00172         const std::string name(pdb_stream.read_string());
00173         pdb_stream.seek(pos); // Seek previous position in stream to read next name offset in the next iteration of this loop
00174 
00175         _named_streams.insert({ name, stream_index });
00176     }
00177 }
