00179 void blink::pdb_reader::read_symbol_table(uint8_t *image_base, std::unordered_map<std::string, void *> &symbols)
00180 {
00181     stream_reader stream(msf_reader::stream(3));
00182 
00183     const pdb_dbi_header &header = stream.read<pdb_dbi_header>();
00184     if (header.signature != 0xFFFFFFFF)
00185         return;
00186 
00187     // Find debug header stream (https://llvm.org/docs/PDB/DbiStream.html#optional-debug-header-stream)
00188     stream.skip(header.module_info_size + header.section_contribution_size + header.section_map_size + header.file_info_size + header.ts_map_size + header.ec_info_size);
00189     const pdb_dbi_debug_header &debug_header = stream.read<pdb_dbi_debug_header>();
00190 
00191     // Read section headers
00192     stream_reader section_stream(msf_reader::stream(debug_header.section_header));
00193 
00194     const size_t num_sections = section_stream.size() / sizeof(pdb_dbi_section_header);
00195     const pdb_dbi_section_header *sections = section_stream.data<pdb_dbi_section_header>();
00196 
00197     // Read symbol table records in CodeView format
00198     stream = msf_reader::stream(header.symbol_record_stream);
00199 
00200     parse_code_view_records(stream, stream.size(), [&](uint16_t tag) {
00201         if (tag != 0x110E) // S_PUB32
00202             return; // Skip all records that are not about public symbols
00203 
00204         const struct PUBSYM32 {
00205             uint32_t flags;
00206             uint32_t offset;
00207             uint16_t section;
00208             const char name[1];
00209         } &sym = *stream.data<const PUBSYM32>();
00210 
00211         if (sym.section == 0 || sym.section > num_sections)
00212             symbols[sym.name] = reinterpret_cast<void *>(static_cast<uintptr_t>(sym.offset)); // Relative address
00213         else
00214             symbols[sym.name] = image_base + sections[sym.section - 1].virtual_address + sym.offset; // Absolute address
00215     }, 4);
00216 }
00217 
00218 void blink::pdb_reader::read_object_files(std::vector<std::filesystem::path> &object_files)
00219 {
00220     stream_reader stream(msf_reader::stream(3));
00221 
00222     const pdb_dbi_header &header = stream.read<pdb_dbi_header>();
00223     if (header.signature != 0xFFFFFFFF)
00224         return;
00225 
00226     // Read module information stream (https://llvm.org/docs/PDB/DbiStream.html#dbi-mod-info-substream)
00227     while (stream.tell() < sizeof(pdb_dbi_header) + header.module_info_size)
00228     {
00229         const pdb_dbi_module_info &info = stream.read<pdb_dbi_module_info>();
00230 
00231         const auto module_name = stream.read_string();
00232         const auto obj_file_name = stream.read_string(); // Contains the name of the ".lib" if this object file is part of a library
00233 
00234         std::filesystem::path path(module_name);
00235 
00236         // Find absolute path to if necessary
00237         if (path.is_relative())
00238         {
00239             if (info.symbol_stream != 65535 /*-1*/)
00240             {
00241                 std::filesystem::path cwd;
00242 
00243                 // Look up current working directory in symbol stream https://llvm.org/docs/PDB/ModiStream.html
00244                 stream_reader stream(msf_reader::stream(info.symbol_stream));
00245                 stream.skip(4); // Skip 32-bit signature (this should be CV_SIGNATURE_C13, aka 4)
00246 
00247                 parse_code_view_records(stream, info.symbol_byte_size - 4, [&](uint16_t tag) {
00248                     if (tag == 0x113d) // S_ENVBLOCK
00249                     {
00250                         stream.skip(1);
00251                         while (stream.tell() < stream.size() && *stream.data() != '\0')
00252                         {
00253                             const auto key = stream.read_string();
00254                             const std::string value(stream.read_string());
00255 
00256                             if (key == "cwd")
00257                             {
00258                                 cwd = value;
00259                                 return;
00260                             }
00261                         }
00262                     }
00263                 });
00264             
00265                 path = cwd / path;
00266             }
00267         }
00268 
00269         object_files.push_back( path.string() );
00270 
00271         stream.align(4);
00272     }
00273 }
