00275 void blink::pdb_reader::read_source_files(std::vector<std::vector<std::filesystem::path>> &source_files, source_file_map &file_map)
00276 {
00277     stream_reader stream(msf_reader::stream(3));
00278 
00279     const pdb_dbi_header &header = stream.read<pdb_dbi_header>();
00280     if (header.signature != 0xFFFFFFFF)
00281         return;
00282 
00283     // Find file information stream (https://llvm.org/docs/PDB/DbiStream.html#file-info-substream)
00284     stream.skip(header.module_info_size + header.section_contribution_size + header.section_map_size);
00285 
00286     const uint16_t num_modules = stream.read<uint16_t>();
00287     stream.skip(2); // Skip old number of file names (see comment on counting the number below)
00288 
00289     // Ignoring since it is not useful: const uint16_t *const module_file_offsets = stream.data<uint16_t>();
00290     const uint16_t *const module_num_source_files = stream.data<uint16_t>(num_modules * sizeof(uint16_t));
00291     const uint32_t *const file_name_offsets = stream.data<uint32_t>(num_modules * sizeof(uint16_t) * 2);
00292 
00293     // Count number of source files instead of reading the value from the header, since there may be more source files that would fit into a 16-bit value
00294     uint32_t num_source_files = 0;
00295     for (uint16_t i = 0; i < num_modules; ++i)
00296         num_source_files += module_num_source_files[i];
00297 
00298     stream.skip(num_modules * sizeof(uint16_t) * 2 + num_source_files * sizeof(uint32_t));
00299     const auto offset = stream.tell();
00300 
00301     // Append source files to array
00302     size_t n = source_files.size();
00303     source_files.resize(n + num_modules);
00304 
00305     uint32_t file_name_offset_index = 0;
00306     for (uint32_t k = 0; k < num_modules; ++k)
00307     {
00308         uint16_t num_files = module_num_source_files[k];
00309         source_files[n + k].resize(num_files);
00310 
00311         for (uint32_t i = 0; i < num_files; ++i)
00312         {
00313             stream.seek(offset + file_name_offsets[file_name_offset_index]);
00314             source_file_indices indices;
00315             indices.module = n + k;
00316             indices.file = i;
00317             source_files[indices.module][indices.file] = stream.read_string();
00318             file_map.insert(std::make_pair(source_files[indices.module][indices.file], indices));
00319             file_name_offset_index += 1;
00320         }
00321     }
00322 }
