00324 void blink::pdb_reader::read_link_info(std::filesystem::path &cwd, std::string &cmd)
00325 {
00326     stream_reader stream(this->stream("/LinkInfo"));
00327 
00328     if (!is_valid() || stream.size() == 0)
00329         return;
00330 
00331     // See https://github.com/Microsoft/microsoft-pdb/blob/master/langapi/include/pdb.h#L500
00332     stream.skip(sizeof(pdb_link_info_header));
00333 
00334     cwd = stream.read_string();
00335     cmd = stream.read_string();
00336     // Followed by another null-terminated string with all linked libraries
00337 }
