00339 void blink::pdb_reader::read_name_hash_table(std::unordered_map<uint32_t, std::string> &names)
00340 {
00341     stream_reader stream(this->stream("/names"));
00342 
00343     if (!is_valid() || stream.size() == 0)
00344         return;
00345 
00346     // Read names stream
00347     const pdb_names_header &header = stream.read<pdb_names_header>();
00348     if (header.signature != 0xEFFEEFFE || header.version != 1)
00349         return;
00350 
00351     // Read the string table
00352     stream.skip(header.names_map_offset);
00353 
00354     const auto size = stream.read<uint32_t>();
00355     names.reserve(size);
00356 
00357     for (uint32_t i = 0; i < size; i++)
00358     {
00359         const auto name_offset = stream.read<uint32_t>();
00360 
00361         // Skip empty entries
00362         if (name_offset == 0)
00363             continue;
00364 
00365         const auto pos = stream.tell();
00366         stream.seek(sizeof(header) + name_offset);
00367         const std::string name(stream.read_string());
00368         stream.seek(pos); // Seek previous position in stream to read next name offset in the next iteration of this loop
00369 
00370         names.insert({ i, name });
00371     }
00372 }
